import{_ as a,c as e,o as t,a0 as r}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Spelarrecensioner","description":"","frontmatter":{},"headers":[],"relativePath":"sv/testimonials.md","filePath":"sv/testimonials.md"}');const l=a({name:"sv/testimonials.md"},[["render",function(a,n,l,i,o,s){return t(),e("div",null,[...n[0]||(n[0]=[r('<h1 id="spelarrecensioner" tabindex="-1">Spelarrecensioner <a class="header-anchor" href="#spelarrecensioner" aria-label="Permalink to &quot;Spelarrecensioner&quot;">​</a></h1><p>Verklig feedback från elitboulespelare som har använt Bouleakademins resurser för att förbättra sitt mentala spel och sina tävlingsprestationer.</p><div class="tip custom-block"><p class="custom-block-title">Autentiskt och anonymt</p><p>Dessa vittnesmål representerar genuin feedback från spelare på olika tävlingsnivåer. Alla vittnesmål är anonyma för att skydda spelarnas integritet och uppmuntra till ärlig delning.</p></div><h2 id="regionala-och-nationella-tavlande" tabindex="-1">Regionala och nationella tävlande <a class="header-anchor" href="#regionala-och-nationella-tavlande" aria-label="Permalink to &quot;Regionala och nationella tävlande&quot;">​</a></h2><h3 id="quot-det-inre-tranarramverket-forandrade-allt-quot" tabindex="-1">&quot;Det inre tränarramverket förändrade allt&quot; <a class="header-anchor" href="#quot-det-inre-tranarramverket-forandrade-allt-quot" aria-label="Permalink to &quot;&amp;quot;Det inre tränarramverket förändrade allt&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag har tävlingsspelat i 12 år och trodde att jag visste allt om boule. Men jag var min egen värsta fiende – jag kritiserade ständigt mig själv efter misstag. Ramverket Inre tränare kontra inre kritiker från modulen Mental styrka gav mig ett helt annat sätt att prata med mig själv under tävling.&quot;</p><p><em>Inom två månader märkte mina lagkamrater skillnaden. Jag var lugnare, återhämtade mig snabbare från dåliga kast och tyckte faktiskt om tävlingen igen. Kom på tredje plats i regionstävlingarna i år – mitt bästa resultat någonsin.</em></p></blockquote><p><strong>— Regional mästare, Frankrike</strong></p><hr><h3 id="quot-antligen-nagon-som-forstar-elitutveckling-quot" tabindex="-1">&quot;Äntligen någon som förstår elitutveckling&quot; <a class="header-anchor" href="#quot-antligen-nagon-som-forstar-elitutveckling-quot" aria-label="Permalink to &quot;&amp;quot;Äntligen någon som förstår elitutveckling&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Det mesta bouleträningen handlar bara om att &#39;öva mer&#39; eller &#39;jobba på din teknik&#39;. Men när man har spelat i över 15 år är det inte problemet. Problemet är att få tillgång till sin teknik under press.&quot;</p><p><em>Zonmodulen förklarade exakt vad jag upplevde – att övertänka under utförandet, att hålla mig i analytiskt läge när jag behövde vara i flow. De praktiska teknikerna för att byta läge har varit banbrytande.</em></p><p><em>Detta är den första resursen jag hittat som faktiskt tar upp det mentala spelet på elitnivå.</em></p></blockquote><p><strong>— Landslagsspelare, Sverige</strong></p><hr><h3 id="quot-workshop-metoden-forvandlade-var-klubb-quot" tabindex="-1">&quot;Workshop-metoden förvandlade vår klubb&quot; <a class="header-anchor" href="#quot-workshop-metoden-forvandlade-var-klubb-quot" aria-label="Permalink to &quot;&amp;quot;Workshop-metoden förvandlade vår klubb&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag är klubbtränare och jag använde workshopguiden för att genomföra en mental matchsession med våra 8 bästa spelare. Ramverket för psykologisk trygghet och det strukturerade diskussionsformatet skapade samtal vi aldrig hade haft förut.&quot;</p><p><em>Spelarna öppnade upp om sina inre kritiker, sina pressreaktioner och sina kommunikationsutmaningar i laget. Det var otroligt kraftfullt. Vi har nu dessa sessioner varje månad, och lagkulturen har förändrats helt.</em></p></blockquote><p><strong>— Klubbtränare, Tyskland</strong></p><hr><h2 id="turneringsspelare" tabindex="-1">Turneringsspelare <a class="header-anchor" href="#turneringsspelare" aria-label="Permalink to &quot;Turneringsspelare&quot;">​</a></h2><h3 id="quot-praktiska-verktyg-som-faktiskt-fungerar-quot" tabindex="-1">&quot;Praktiska verktyg som faktiskt fungerar&quot; <a class="header-anchor" href="#quot-praktiska-verktyg-som-faktiskt-fungerar-quot" aria-label="Permalink to &quot;&amp;quot;Praktiska verktyg som faktiskt fungerar&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag har läst böcker om idrottspsykologi förut, men de är alltid för generella eller för akademiska. Målmallen och Dagboksmallen från Pétanque Academy är precis vad jag behövde – praktiska, specifika för boule och omedelbart användbara.&quot;</p><p><em>Jag använde målmallen och hade en tydlig 3-månaders utvecklingsplan på 30 minuter. Dagboksmallen hjälper mig att spåra inte bara resultat utan även mental prestation. Dessa verktyg är guld värda.</em></p></blockquote><p><strong>— Turneringsspelare, Spanien</strong></p><hr><h3 id="quot-mindfulnessteknikerna-fungerar-i-konkurrens-quot" tabindex="-1">&quot;Mindfulnessteknikerna fungerar i konkurrens&quot; <a class="header-anchor" href="#quot-mindfulnessteknikerna-fungerar-i-konkurrens-quot" aria-label="Permalink to &quot;&amp;quot;Mindfulnessteknikerna fungerar i konkurrens&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag var skeptisk till mindfulness – det verkade för &#39;mjukt&#39; för tävlingssporter. Men teknikerna i Mindfulness-modulen är praktiska och specifika. 3-andetagsåterställningen, kroppsskanningen för spänningar, övningarna för fokus i nuet.&quot;</p><p><em>Jag tränar 10 minuter varje morgon och kan nu använda dessa tekniker under tävling. När jag känner att pressen ökar har jag verktyg för att hantera den. Detta har gjort en mätbar skillnad i min prestation.</em></p></blockquote><p><strong>— Turneringsspelare, Nederländerna</strong></p><hr><h3 id="quot-att-forsta-flodestillstand-frigjorde-min-potential-quot" tabindex="-1">&quot;Att förstå flödestillstånd frigjorde min potential&quot; <a class="header-anchor" href="#quot-att-forsta-flodestillstand-frigjorde-min-potential-quot" aria-label="Permalink to &quot;&amp;quot;Att förstå flödestillstånd frigjorde min potential&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag hade haft spel där allting klickade – där jag inte tänkte, utan bara spelade perfekt. Men jag visste inte hur jag skulle komma åt det tillståndet konsekvent. Zonmodulen förklarade vetenskapen bakom det och gav mig praktiska tekniker.&quot;</p><p><em>Att lära sig om transient hypofrontalitet, förstå växlingen mellan planering och utförande, öva på flödestriggers – den här kunskapen har gjort de där topprestationstillstånden mycket mer lättillgängliga. Jag spelar min bästa boule någonsin.</em></p></blockquote><p><strong>— Regional spelare, Frankrike</strong></p><hr><h2 id="lagspelare" tabindex="-1">Lagspelare <a class="header-anchor" href="#lagspelare" aria-label="Permalink to &quot;Lagspelare&quot;">​</a></h2><h3 id="quot-blev-lagkamraten-alla-vill-ha-quot" tabindex="-1">&quot;Blev lagkamraten alla vill ha&quot; <a class="header-anchor" href="#quot-blev-lagkamraten-alla-vill-ha-quot" aria-label="Permalink to &quot;&amp;quot;Blev lagkamraten alla vill ha&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag var tekniskt stark men hade det svårt i lagtävlingar. Modulen i lagdynamik visade mig att det att vara en bra lagspelare inte bara handlar om att göra bra kast – det handlar om kommunikation, tillit och psykologisk trygghet.&quot;</p><p><em>Jag lärde mig att uttrycka förtroende, att kommunicera strategi tydligt, att stödja lagkamrater efter misstag. Inom några månader gick jag från att vara undviken till att vara eftertraktad som partner. Vann regionsmästerskapet i lag i år.</em></p></blockquote><p><strong>— Lagspelare, Italien</strong></p><hr><h3 id="quot-kommunikationsramverket-raddade-vart-partnerskap-quot" tabindex="-1">&quot;Kommunikationsramverket räddade vårt partnerskap&quot; <a class="header-anchor" href="#quot-kommunikationsramverket-raddade-vart-partnerskap-quot" aria-label="Permalink to &quot;&amp;quot;Kommunikationsramverket räddade vårt partnerskap&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Min vanliga partner och jag hade spänningar – olika spelstilar, dålig kommunikation och frustration. Team Player-modulen gav oss ett ramverk för att diskutera det konstruktivt.&quot;</p><p><em>Vi lärde oss om kommunikationsmönster, om att bygga förtroende, om att skapa psykologisk trygghet. Vi hade ärliga samtal med hjälp av workshopformatet. Vårt partnerskap är starkare än någonsin, och våra resultat visar det.</em></p></blockquote><p><strong>— Dubbellag, Norge</strong></p><hr><h2 id="tranare-och-utbildare" tabindex="-1">Tränare och utbildare <a class="header-anchor" href="#tranare-och-utbildare" aria-label="Permalink to &quot;Tränare och utbildare&quot;">​</a></h2><h3 id="quot-sa-har-ser-elitcoaching-ut-quot" tabindex="-1">&quot;Så här ser elitcoaching ut&quot; <a class="header-anchor" href="#quot-sa-har-ser-elitcoaching-ut-quot" aria-label="Permalink to &quot;&amp;quot;Så här ser elitcoaching ut&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Jag har tränat boule i 20 år, mest med fokus på teknik. Men jag såg spelare med utmärkt teknik misslyckas under press. Utbildningsmodulerna gav mig ramverket för att systematiskt ta itu med det mentala spelet.&quot;</p><p><em>Träningslägrets guide hjälpte mig att strukturera ett helgprogram som kombinerade tekniskt arbete med mental spelträning. Feedbacken från spelarna var otrolig – de sa att det var den mest värdefulla träningen de någonsin hade deltagit i.</em></p></blockquote><p><strong>— Tränare, Frankrike</strong></p><hr><h3 id="quot-evidensbaserad-metod-for-mental-traning-quot" tabindex="-1">&quot;Evidensbaserad metod för mental träning&quot; <a class="header-anchor" href="#quot-evidensbaserad-metod-for-mental-traning-quot" aria-label="Permalink to &quot;&amp;quot;Evidensbaserad metod för mental träning&amp;quot;&quot;">​</a></h3><blockquote><p>*&quot;Det jag uppskattar mest är att det här inte bara är motivationssnack. Innehållet är baserat på faktisk psykologisk forskning – flödesvetenskap, mindfulnessstudier, prestationspsykologi. Men det översätts till praktiska, handlingsbara tekniker.&quot;</p><p><em>Jag använder dessa moduler som grund för mental spelcoachning med mina elitspelare. Det strukturerade tillvägagångssättet, de tydliga ramverken, de praktiska övningarna – detta är innehåll på professionell nivå.</em></p></blockquote><p><strong>— Idrottspsykolog och petanquetränare, Storbritannien</strong></p><hr><h2 id="vanliga-teman" tabindex="-1">Vanliga teman <a class="header-anchor" href="#vanliga-teman" aria-label="Permalink to &quot;Vanliga teman&quot;">​</a></h2><h3 id="vad-spelarna-vardesatter-mest" tabindex="-1">Vad spelarna värdesätter mest <a class="header-anchor" href="#vad-spelarna-vardesatter-mest" aria-label="Permalink to &quot;Vad spelarna värdesätter mest&quot;">​</a></h3><p>Baserat på feedback framhäver spelarna konsekvent:</p><ol><li><strong>Praktiskt, handlingsbart innehåll</strong> - Inte teori, utan tekniker du kan använda idag</li><li><strong>Pétanque-specifik</strong> - Designad för de unika utmaningarna med petanque</li><li><strong>Fokus på elitnivå</strong> - Tar upp det mentala spelet, inte grundläggande teknik</li><li><strong>Strukturerade ramverk</strong> - Tydliga system, inte vaga råd</li><li><strong>Gratis och tillgänglig</strong> - Inga betalväggar, tillgängligt för alla</li></ol><h3 id="matbara-resultat" tabindex="-1">Mätbara resultat <a class="header-anchor" href="#matbara-resultat" aria-label="Permalink to &quot;Mätbara resultat&quot;">​</a></h3><p>Spelare rapporterar förbättringar i:</p><ul><li>Tävlingsprestationer och resultat</li><li>Konsekvens under press</li><li>Återhämtningstid efter misstag</li><li>Teamkommunikation och dynamik</li><li>Njutning av tävling</li><li>Mental motståndskraft</li></ul><h2 id="dela-din-erfarenhet" tabindex="-1">Dela din erfarenhet <a class="header-anchor" href="#dela-din-erfarenhet" aria-label="Permalink to &quot;Dela din erfarenhet&quot;">​</a></h2><p>Har du använt Pétanque Academys resurser? Vi vill gärna höra om dina erfarenheter.</p><p><strong>Skicka din recension via e-post till:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Reference" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Omfatta:</strong></p><ul><li>Din erfarenhetsnivå</li><li>Vilka resurser du använde</li><li>Vilken inverkan de hade</li><li>Om vi kan dela din feedback (namn valfritt)</li></ul><p>Din berättelse kan hjälpa andra spelare att upptäcka dessa resurser.</p><hr><h2 id="kom-igang" tabindex="-1">Kom igång <a class="header-anchor" href="#kom-igang" aria-label="Permalink to &quot;Kom igång&quot;">​</a></h2><p>Redo att utveckla ditt mentala spel?</p><div class="tip custom-block"><p class="custom-block-title">Börja här</p><ul><li><strong>Nybörjare på mental träning?</strong> → <a href="/sv/utbildning/zonen/">Zonen</a></li><li><strong>Kämpar du med press?</strong> → <a href="/sv/utbildning/mental-styrka/">Mental styrka</a></li><li><strong>Utmaningar i laget?</strong> → <a href="/sv/utbildning/lagspelare/">Lagdynamik</a></li><li><strong>Vill du ha struktur?</strong> → <a href="/sv/målmall">Målmall</a></li></ul></div>',64)])])}]]);export{n as __pageData,l as default};
